export interface GameEventParams {
  game_id: 'survivor' | 'snake' | 'moonrun' | 'dungeon3d' | 'merge' | 'pet';
  game_name?: string;
  score?: number;
  level?: number;
  duration_sec?: number;
  reason?: string;
  [key: string]: any;
}

export class AnalyticsService {
  public static readonly MEASUREMENT_ID = 'G-6MBFKX8BKF';

  /**
   * 追蹤單頁應用 (SPA) 虛擬頁面路徑
   */
  public static trackPageView(path: string, title?: string): void {
    if (typeof window === 'undefined' || typeof (window as any).gtag !== 'function') return;

    const cleanPath = path.replace(/^#\/?/, '').split('?')[0];
    const normalizedPath = cleanPath ? `/game/${cleanPath}` : '/game/';
    const pageTitle = title ? `${title} | SNEK Arcade` : document.title;

    (window as any).gtag('event', 'page_view', {
      page_title: pageTitle,
      page_location: window.location.href,
      page_path: normalizedPath,
    });
  }

  /**
   * 發送自訂分析事件 (如開始遊戲、結算、升級)
   */
  public static trackEvent(eventName: string, params: Record<string, any> = {}): void {
    if (typeof window === 'undefined' || typeof (window as any).gtag !== 'function') return;

    (window as any).gtag('event', eventName, {
      ...params,
      timestamp: Date.now(),
    });
  }

  /**
   * 遊戲開始事件
   */
  public static trackGameStart(gameId: GameEventParams['game_id'], extraParams: Record<string, any> = {}): void {
    this.trackEvent('game_start', {
      game_id: gameId,
      ...extraParams,
    });
  }

  /**
   * 遊戲結束 / 結算事件
   */
  public static trackGameOver(params: GameEventParams): void {
    this.trackEvent('game_over', params);
  }
}
